private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } } } public class Airplane extends Vehicle{
private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } }
@Override public double move(double distance){ this.landing_gear(false); System.out.println("Moving"); this.landing_gear(true); return distance / this.speed; } } public class Airplane extends Vehicle{
private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } }
@Override public double move(double distance){ this.landing_gear(false); System.out.println("Moving"); this.landing_gear(true); return distance / this.speed; } } public class Airplane extends Vehicle{
private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } }
@Override public double move(double distance){ this.landing_gear(false); System.out.println("Moving"); this.landing_gear(true); return distance / this.speed; } } public class Airplane extends Vehicle{
private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } }
@Override public double move(double distance){ this.landing_gear(false); System.out.println("Moving"); this.landing_gear(true); return distance / this.speed; }
@Override public String describe(){ return String.format("I am an airplane with a wingspan of %f and capacity %d", this.wingspan, this.capacity); } } public class Airplane extends Vehicle{
private double wingspan; private int capacity;
public Airplane(String name, double wingspan, int capacity){ super(name); this.wingspan = wingspan; this.capacity = capacity; }
public void landing_gear(boolean set){ if(set){ System.out.println("Landing gear down"); }else{ System.out.println("Landing gear up"); } }
@Override public double move(double distance){ this.landing_gear(false); System.out.println("Moving"); this.landing_gear(true); return distance / this.speed; }
@Override public String describe(){ return String.format("I am an airplane with a wingspan of %f and capacity %d", this.wingspan, this.capacity); } } public class Main{
public static void main(String[] args){ Vehicle vehicle = new Vehicle("Boat"); Airplane airplane = new Airplane("Plane", 175, 53); System.out.println(vehicle.move(10)); System.out.println(airplane.move(10)); System.out.println(vehicle.describe()); System.out.println(airplane.describe()); } } public class Main{
public static void main(String[] args){ Vehicle vehicle = new Vehicle("Boat"); Airplane airplane = new Airplane("Plane", 175, 53); System.out.println(vehicle.move(10)); System.out.println(airplane.move(10)); System.out.println(vehicle.describe()); System.out.println(airplane.describe()); } } Moving 10.0 Landing gear up Moving Landing gear down 10.0
